        bytes32 hash = EIP712Hash.config({
            sponsor: account,
            validator: config.validator,
            configId: configId,
            lockTag: lockTag,
            expires: enableData.expires,
            nonce: enableData.nonce,
            validatorConfig: config.validatorConfig,
