        hash = keccak256(
            abi.encode(
                TYPEHASH.CONFIG,
                sponsor,
                validator,
                configId,
                lockTag,
                expires,
                keccak256(validatorConfig),
                nonce,
                keccak256(abi.encodePacked(chainIds))
            )
        );
    }
}

